        case Z_DENTRY_TAG_FILE: return z_t379_eq(a.data.file, b.data.file);
        case Z_DENTRY_TAG_DIRECTORY: return z_t384_eq(a.data.directory, b.data.directory);
        case Z_DENTRY_TAG_MOUNT: return z_t389_eq(a.data.mount, b.data.mount);
